+func (b *outlierDetectionBalancer) appendIfPresent(addr string, scw *subConnWrapper) *addressInfo {
+	obj, ok := b.addrs[addr]
+	if !ok {
+		return nil
+	}
+
+	obj.sws = append(obj.sws, scw)
