+func (b *outlierDetectionBalancer) removeSubConnFromAddressesMapEntry(scw *subConnWrapper) {
+	obj := (*addressInfo)(atomic.LoadPointer(&scw.addressInfo))
+	if obj == nil {
+		return
+	}
+	for i, sw := range obj.sws {
+		if scw == sw {
+			obj.sws = append(obj.sws[:i], obj.sws[i+1:]...)
+			break
+		}
+	}
