+	// called manually), will never hit in production.
+	if b.intervalTimer != nil {
+		b.intervalTimer.Stop()
+	}
+	b.intervalTimer = afterFunc(b.cfg.Interval, func() {
+		b.intervalTimerAlgorithm()
+	})
+}
